#!/usr/bin/env node

'use strict';

// Boot an Android emulator, install a debug APK, and launch it.
//
// Exit codes: 0 = launched · 1 = boot failed · 2 = timeout
//             3 = setup error · 4 = install/launch failed
//
// Usage:
//   node launch-emulator.cjs [--project-dir DIR] [--apk PATH]
//     [--avd NAME] [--timeout 300]
//   node launch-emulator.cjs [--project-dir DIR] --shutdown

var childProcess = require('child_process');
var fs = require('fs');
var os = require('os');
var path = require('path');

function isFile(file) {
  try {
    return fs.statSync(file).isFile();
  } catch (_error) {
    return false;
  }
}

function sleep(milliseconds) {
  return new Promise(function (resolve) {
    setTimeout(resolve, milliseconds);
  });
}

function platformExecutable(name, platform) {
  return platform === 'win32' ? name + '.exe' : name;
}

function decodeLocalPropertiesPath(value) {
  return value.trim().replace(/\\:/g, ':').replace(/\\\\/g, '\\').replace(/\\ /g, ' ');
}

function sdkRoots(projectDirectory, environment, platform, homeDirectory) {
  var roots = [];

  function add(value) {
    if (!value) {
      return;
    }
    var resolved = path.resolve(value);
    if (roots.indexOf(resolved) === -1) {
      roots.push(resolved);
    }
  }

  add(environment.ANDROID_HOME);
  add(environment.ANDROID_SDK_ROOT);

  var localProperties = path.join(projectDirectory, 'local.properties');
  if (isFile(localProperties)) {
    var match = fs.readFileSync(localProperties, 'utf8').match(/^sdk\.dir=(.*)$/m);
    if (match) {
      add(decodeLocalPropertiesPath(match[1]));
    }
  }

  if (platform === 'darwin') {
    add(path.join(homeDirectory, 'Library', 'Android', 'sdk'));
  } else if (platform === 'win32') {
    add(
      environment.LOCALAPPDATA
        ? path.join(environment.LOCALAPPDATA, 'Android', 'Sdk')
        : path.join(homeDirectory, 'AppData', 'Local', 'Android', 'Sdk'),
    );
  } else {
    add(path.join(homeDirectory, 'Android', 'Sdk'));
  }

  return roots;
}

function findSdkTool(sdkRoot, relativeDirectory, name, platform) {
  var candidate = path.join(sdkRoot, relativeDirectory, platformExecutable(name, platform));
  return isFile(candidate) ? candidate : '';
}

function findOnPath(name, environment, platform) {
  var executableNames = [platformExecutable(name, platform)];
  var pathValue = environment.PATH || environment.Path || '';
  var separator = platform === 'win32' ? ';' : ':';
  var directories = pathValue.split(separator).filter(Boolean);

  if (platform === 'win32' && path.extname(name) === '') {
    var extensions = (environment.PATHEXT || '.EXE;.CMD;.BAT;.COM').split(';').filter(Boolean);
    executableNames = extensions.map(function (extension) {
      return name + extension.toLowerCase();
    });
  }

  for (var directoryIndex = 0; directoryIndex < directories.length; directoryIndex += 1) {
    for (var nameIndex = 0; nameIndex < executableNames.length; nameIndex += 1) {
      var candidate = path.join(directories[directoryIndex], executableNames[nameIndex]);
      if (isFile(candidate)) {
        return candidate;
      }
    }
  }
  return '';
}

function resolveAndroidTool(
  projectDirectory,
  relativeDirectory,
  name,
  environment,
  platform,
  homeDirectory,
) {
  var roots = sdkRoots(projectDirectory, environment, platform, homeDirectory);
  for (var index = 0; index < roots.length; index += 1) {
    var tool = findSdkTool(roots[index], relativeDirectory, name, platform);
    if (tool) {
      return { path: tool, sdkRoot: roots[index] };
    }
  }
  return {
    path: findOnPath(name, environment, platform),
    sdkRoot: '',
  };
}

function walkFiles(directory, matches, results) {
  var entries;
  try {
    entries = fs.readdirSync(directory, { withFileTypes: true });
  } catch (_error) {
    return;
  }

  entries.sort(function (left, right) {
    return left.name.localeCompare(right.name);
  });
  for (var index = 0; index < entries.length; index += 1) {
    var entry = entries[index];
    var file = path.join(directory, entry.name);
    if (entry.isDirectory()) {
      walkFiles(file, matches, results);
    } else if (entry.isFile() && matches(file)) {
      results.push(file);
    }
  }
}

function findDebugApk(projectDirectory) {
  var files = [];
  walkFiles(
    projectDirectory,
    function (file) {
      return (
        file.toLowerCase().slice(-4) === '.apk' &&
        file.replace(/\\/g, '/').indexOf('/outputs/apk/debug/') !== -1
      );
    },
    files,
  );
  files.sort(function (left, right) {
    var modified = fs.statSync(right).mtimeMs - fs.statSync(left).mtimeMs;
    return modified || left.localeCompare(right);
  });
  return files.length > 0 ? path.resolve(files[0]) : '';
}

function run(command, args, timeout, options) {
  return childProcess.spawnSync(command, args, {
    cwd: options && options.cwd,
    encoding: options && options.binary ? undefined : 'utf8',
    env: (options && options.env) || process.env,
    maxBuffer: 64 * 1024 * 1024,
    timeout: timeout,
    windowsHide: true,
  });
}

function successful(result) {
  return !result.error && result.status === 0;
}

function emulatorSerials(output) {
  return String(output || '')
    .split(/\r?\n/)
    .map(function (line) {
      var match = line.match(/^(emulator-\d+)\s+device(?:\s|$)/);
      return match ? match[1] : '';
    })
    .filter(Boolean);
}

function listedEmulatorSerials(output) {
  return String(output || '')
    .split(/\r?\n/)
    .map(function (line) {
      var match = line.match(/^(emulator-\d+)\s+\S+/);
      return match ? match[1] : '';
    })
    .filter(Boolean);
}

function onlineEmulators(adb, environment) {
  var result = run(adb, ['devices'], 10000, { env: environment });
  return successful(result) ? emulatorSerials(result.stdout) : [];
}

function emulatorAvdName(adb, serial, environment) {
  var result = run(adb, ['-s', serial, 'emu', 'avd', 'name'], 10000, {
    env: environment,
  });
  if (!successful(result)) {
    return '';
  }
  var names = String(result.stdout || '')
    .split(/\r?\n/)
    .map(function (line) {
      return line.trim();
    })
    .filter(function (line) {
      return line && line !== 'OK';
    });
  return names.length > 0 ? names[0] : '';
}

function findAapt(roots, platform) {
  var versions = [];
  for (var rootIndex = 0; rootIndex < roots.length; rootIndex += 1) {
    var buildTools = path.join(roots[rootIndex], 'build-tools');
    var entries;
    try {
      entries = fs.readdirSync(buildTools, { withFileTypes: true });
    } catch (_error) {
      continue;
    }
    for (var entryIndex = 0; entryIndex < entries.length; entryIndex += 1) {
      if (entries[entryIndex].isDirectory()) {
        versions.push({
          directory: path.join(buildTools, entries[entryIndex].name),
          version: entries[entryIndex].name,
        });
      }
    }
  }

  versions.sort(function (left, right) {
    return right.version.localeCompare(left.version, undefined, { numeric: true });
  });
  var names = ['aapt2', 'aapt'];
  for (var nameIndex = 0; nameIndex < names.length; nameIndex += 1) {
    for (var versionIndex = 0; versionIndex < versions.length; versionIndex += 1) {
      var candidate = path.join(
        versions[versionIndex].directory,
        platformExecutable(names[nameIndex], platform),
      );
      if (isFile(candidate)) {
        return candidate;
      }
    }
  }
  return '';
}

function packageFromBadging(output) {
  var match = String(output || '').match(/^package:\s+name='([^']+)'/m);
  return match ? match[1] : '';
}

function stopProcessTree(pid, platform) {
  if (!pid) {
    return;
  }
  if (platform === 'win32') {
    childProcess.spawnSync('taskkill.exe', ['/pid', String(pid), '/t', '/f'], {
      stdio: 'ignore',
      windowsHide: true,
    });
    return;
  }
  try {
    process.kill(-pid, 'SIGTERM');
  } catch (_error) {
    try {
      process.kill(pid, 'SIGTERM');
    } catch (_ignored) {
      // The emulator already exited.
    }
  }
}

function stopEmulator(adb, serial, environment, pid, platform) {
  if (serial) {
    var result = run(adb, ['-s', serial, 'emu', 'kill'], 15000, {
      env: environment,
    });
    if (successful(result)) {
      return;
    }
  }
  stopProcessTree(pid, platform);
}

function commandFailureDetails(result) {
  var details = [];
  if (result && result.error) {
    details.push(result.error.message);
  }
  if (result && result.stderr) {
    details.push(String(result.stderr).trim());
  }
  if (result && result.stdout) {
    details.push(String(result.stdout).trim());
  }
  return details.filter(Boolean).join('\n').slice(0, 4000);
}

function parseArguments(args) {
  var options = {
    projectDirectory: process.cwd(),
    apk: '',
    avd: '',
    timeoutSeconds: 300,
    shutdown: false,
  };
  for (var index = 0; index < args.length; index += 1) {
    var argument = args[index];
    if (
      argument !== '--project-dir' &&
      argument !== '--apk' &&
      argument !== '--avd' &&
      argument !== '--timeout' &&
      argument !== '--shutdown'
    ) {
      return { error: 'Unknown arg: ' + argument };
    }
    if (argument === '--shutdown') {
      options.shutdown = true;
      continue;
    }
    if (index + 1 >= args.length) {
      return { error: 'Missing value for ' + argument };
    }
    var value = args[index + 1];
    index += 1;
    if (argument === '--project-dir') {
      options.projectDirectory = path.resolve(value);
    } else if (argument === '--apk') {
      options.apk = path.resolve(value);
    } else if (argument === '--avd') {
      options.avd = value;
    } else {
      options.timeoutSeconds = Number(value);
    }
  }
  if (
    !Number.isFinite(options.timeoutSeconds) ||
    options.timeoutSeconds <= 0 ||
    Math.floor(options.timeoutSeconds) !== options.timeoutSeconds
  ) {
    return { error: '--timeout must be a positive integer' };
  }
  options.projectDirectory = path.resolve(options.projectDirectory);
  return { options: options };
}

function ownedRunningSerial(session, runningSerials) {
  return session &&
    session.started === true &&
    typeof session.serial === 'string' &&
    runningSerials.indexOf(session.serial) !== -1
    ? session.serial
    : '';
}

function preferredEmulatorSerial(session, runningSerials) {
  return session &&
    typeof session.serial === 'string' &&
    runningSerials.indexOf(session.serial) !== -1
    ? session.serial
    : runningSerials[0] || '';
}

async function main(args) {
  var parsed = parseArguments(args);
  if (parsed.error) {
    console.log('LAUNCH_STATUS:ERROR');
    console.log(parsed.error);
    return 3;
  }

  var options = parsed.options;
  var environment = Object.assign({}, process.env);
  var platform = process.platform;
  var homeDirectory = os.homedir();
  var adbResult = resolveAndroidTool(
    options.projectDirectory,
    'platform-tools',
    'adb',
    environment,
    platform,
    homeDirectory,
  );
  if (!adbResult.path) {
    console.log('LAUNCH_STATUS:ERROR');
    console.log('adb not found in the Android SDK or PATH');
    return 3;
  }

  var androidHome = adbResult.sdkRoot;
  if (androidHome) {
    environment.ANDROID_HOME = androidHome;
    environment.ANDROID_SDK_ROOT = androidHome;
  }

  var sessionFile = path.join(
    options.projectDirectory,
    '.locofy',
    'agent',
    'emulator-session.json',
  );
  if (options.shutdown) {
    if (!isFile(sessionFile)) {
      console.log('LAUNCH_STATUS:SHUTDOWN');
      console.log('EMULATORS_STOPPED:0');
      return 0;
    }

    var session;
    try {
      session = JSON.parse(fs.readFileSync(sessionFile, 'utf8'));
    } catch (_error) {
      console.log('LAUNCH_STATUS:ERROR');
      console.log('invalid emulator session state: ' + sessionFile);
      return 3;
    }

    if (
      !session.started ||
      !session.serial ||
      !Number.isSafeInteger(session.pid) ||
      session.pid <= 0
    ) {
      fs.rmSync(sessionFile, { force: true });
      console.log('LAUNCH_STATUS:SHUTDOWN');
      console.log('EMULATORS_STOPPED:0');
      return 0;
    }

    var devicesResult = run(adbResult.path, ['devices'], 10000, { env: environment });
    var runningSerials = successful(devicesResult)
      ? listedEmulatorSerials(devicesResult.stdout)
      : [];
    var ownedSerial = ownedRunningSerial(session, runningSerials);
    if (!ownedSerial) {
      fs.rmSync(sessionFile, { force: true });
      console.log('LAUNCH_STATUS:SHUTDOWN');
      console.log('EMULATORS_STOPPED:0');
      return 0;
    }

    stopEmulator(adbResult.path, ownedSerial, environment, session.pid, platform);
    fs.rmSync(sessionFile, { force: true });
    console.log('LAUNCH_STATUS:SHUTDOWN');
    console.log('EMULATORS_STOPPED:1');
    return 0;
  }

  var apk = options.apk || findDebugApk(options.projectDirectory);
  if (!apk || !isFile(apk)) {
    console.log('LAUNCH_STATUS:ERROR');
    console.log('no debug APK (build first)');
    return 3;
  }

  var listedResult = run(adbResult.path, ['devices'], 10000, { env: environment });
  if (!successful(listedResult)) {
    console.log('LAUNCH_STATUS:ERROR');
    console.log('adb devices failed');
    return 3;
  }
  var listedBeforeStart = listedEmulatorSerials(listedResult.stdout);
  var serials = emulatorSerials(listedResult.stdout);
  var existingSession = null;
  if (isFile(sessionFile)) {
    try {
      existingSession = JSON.parse(fs.readFileSync(sessionFile, 'utf8'));
    } catch (_error) {
      // A successful launch replaces invalid stale session state.
    }
  }
  var preferredSerial = preferredEmulatorSerial(existingSession, serials);
  if (preferredSerial) {
    serials = [preferredSerial].concat(
      serials.filter(function (serial) {
        return serial !== preferredSerial;
      }),
    );
  }
  var startedEmulator = serials.length === 0;
  var avd = options.avd;
  var emulatorResult = { path: '', sdkRoot: '' };
  if (startedEmulator) {
    emulatorResult = resolveAndroidTool(
      options.projectDirectory,
      'emulator',
      'emulator',
      environment,
      platform,
      homeDirectory,
    );
    if (!emulatorResult.path) {
      console.log('LAUNCH_STATUS:ERROR');
      console.log('emulator not found in the Android SDK or PATH');
      return 3;
    }

    androidHome = androidHome || emulatorResult.sdkRoot;
    if (androidHome) {
      environment.ANDROID_HOME = androidHome;
      environment.ANDROID_SDK_ROOT = androidHome;
    }

    if (!avd) {
      var avdResult = run(emulatorResult.path, ['-list-avds'], 30000, { env: environment });
      if (successful(avdResult)) {
        avd = String(avdResult.stdout || '')
          .split(/\r?\n/)
          .map(function (line) {
            return line.trim();
          })
          .filter(Boolean)[0];
      }
    }
    if (!avd) {
      console.log('LAUNCH_STATUS:ERROR');
      console.log('no AVD available (create one in Android Studio)');
      return 3;
    }
  }

  console.log(
    'LAUNCH_CONFIG:avd=' +
      (avd || 'reuse') +
      ' apk=' +
      apk +
      ' timeout=' +
      options.timeoutSeconds +
      's',
  );

  var emulatorPid = 0;
  var emulatorLog = '';
  var emulatorStartError = '';
  var emulatorExited = false;
  if (startedEmulator) {
    console.log('Booting emulator (detached) ...');
    var logDirectory = path.join(options.projectDirectory, '.locofy', 'agent', 'build-logs');
    fs.mkdirSync(logDirectory, { recursive: true });
    emulatorLog = path.join(logDirectory, 'emulator.log');
    var logDescriptor = fs.openSync(emulatorLog, 'a');
    var emulatorProcess;
    try {
      emulatorProcess = childProcess.spawn(
        emulatorResult.path,
        [
          '-avd',
          avd,
          '-no-snapshot-save',
          '-no-boot-anim',
          '-netdelay',
          'none',
          '-netspeed',
          'full',
        ],
        {
          detached: true,
          env: environment,
          stdio: ['ignore', logDescriptor, logDescriptor],
          windowsHide: true,
        },
      );
      emulatorProcess.on('error', function (error) {
        emulatorStartError = error.message;
      });
      emulatorProcess.on('exit', function (code, signal) {
        emulatorExited = true;
        if (!emulatorStartError && code !== 0) {
          emulatorStartError =
            'emulator exited with code ' + code + (signal ? ' (' + signal + ')' : '');
        }
      });
      emulatorPid = emulatorProcess.pid || 0;
      emulatorProcess.unref();
    } finally {
      fs.closeSync(logDescriptor);
    }
    if (!emulatorPid) {
      console.log('LAUNCH_STATUS:ERROR');
      console.log('emulator failed to start');
      return 3;
    }
    console.log('EMULATOR_PID:' + emulatorPid);
    console.log('EMULATOR_LOG:' + emulatorLog);
  }

  console.log('Waiting for device ...');
  var serial = startedEmulator ? '' : serials[0];
  var deviceDeadline = Date.now() + Math.min(120, options.timeoutSeconds) * 1000;
  while (!serial && !emulatorStartError && !emulatorExited && Date.now() < deviceDeadline) {
    serials = onlineEmulators(adbResult.path, environment);
    if (startedEmulator) {
      var matchingNewSerials = serials.filter(function (candidate) {
        return (
          listedBeforeStart.indexOf(candidate) === -1 &&
          emulatorAvdName(adbResult.path, candidate, environment) === avd
        );
      });
      if (matchingNewSerials.length === 1) {
        serial = matchingNewSerials[0];
      } else if (matchingNewSerials.length > 1) {
        stopProcessTree(emulatorPid, platform);
        console.log('LAUNCH_STATUS:ERROR');
        console.log('could not identify the emulator started by this workflow');
        return 3;
      }
    } else if (serials.length > 0) {
      serial = serials[0];
    }
    if (!serial) {
      await sleep(1000);
    }
  }
  if (!serial) {
    stopProcessTree(emulatorPid, platform);
    if (emulatorStartError || emulatorExited) {
      console.log('LAUNCH_STATUS:BOOT_FAILED');
      console.log(emulatorStartError || 'emulator exited before the device came online');
      if (emulatorLog) console.log('EMULATOR_LOG:' + emulatorLog);
      return 1;
    }
    console.log('LAUNCH_STATUS:TIMEOUT');
    console.log('device never came online');
    if (emulatorLog) console.log('EMULATOR_LOG:' + emulatorLog);
    return 2;
  }

  var bootDeadline = Date.now() + options.timeoutSeconds * 1000;
  var booted = false;
  while (Date.now() < bootDeadline) {
    var bootResult = run(
      adbResult.path,
      ['-s', serial, 'shell', 'getprop', 'sys.boot_completed'],
      10000,
      { env: environment },
    );
    if (successful(bootResult) && String(bootResult.stdout || '').trim() === '1') {
      booted = true;
      break;
    }
    await sleep(3000);
  }
  if (!booted) {
    stopEmulator(adbResult.path, serial, environment, emulatorPid, platform);
    console.log('LAUNCH_STATUS:TIMEOUT');
    console.log('sys.boot_completed never 1');
    if (emulatorLog) console.log('EMULATOR_LOG:' + emulatorLog);
    return 2;
  }
  run(adbResult.path, ['-s', serial, 'shell', 'input', 'keyevent', '82'], 20000, {
    env: environment,
  });

  console.log('Installing APK ...');
  var installResult = run(adbResult.path, ['-s', serial, 'install', '-r', '-t', apk], 180000, {
    env: environment,
  });
  if (!successful(installResult)) {
    stopEmulator(adbResult.path, serial, environment, emulatorPid, platform);
    console.log('LAUNCH_STATUS:INSTALL_FAILED');
    console.log('adb install failed');
    var installDetails = commandFailureDetails(installResult);
    if (installDetails) console.log(installDetails);
    if (emulatorLog) console.log('EMULATOR_LOG:' + emulatorLog);
    return 4;
  }

  var roots = sdkRoots(options.projectDirectory, environment, platform, homeDirectory);
  var aapt = findAapt(roots, platform);
  var packageName = '';
  if (aapt) {
    var badgingResult = run(aapt, ['dump', 'badging', apk], 30000, {
      env: environment,
    });
    if (successful(badgingResult)) {
      packageName = packageFromBadging(badgingResult.stdout);
    }
  }
  if (!packageName) {
    stopEmulator(adbResult.path, serial, environment, emulatorPid, platform);
    console.log('LAUNCH_STATUS:INSTALL_FAILED');
    console.log('could not resolve the installed APK package id with aapt/aapt2');
    if (emulatorLog) console.log('EMULATOR_LOG:' + emulatorLog);
    return 4;
  }

  console.log('Launching ' + packageName + ' ...');
  var launchResult = run(
    adbResult.path,
    [
      '-s',
      serial,
      'shell',
      'monkey',
      '-p',
      packageName,
      '-c',
      'android.intent.category.LAUNCHER',
      '1',
    ],
    30000,
    { env: environment },
  );
  if (!successful(launchResult)) {
    stopEmulator(adbResult.path, serial, environment, emulatorPid, platform);
    console.log('LAUNCH_STATUS:INSTALL_FAILED');
    console.log('launch failed for ' + packageName);
    var launchDetails = commandFailureDetails(launchResult);
    if (launchDetails) console.log(launchDetails);
    if (emulatorLog) console.log('EMULATOR_LOG:' + emulatorLog);
    return 4;
  }

  console.log('LAUNCH_STATUS:SUCCESS');
  console.log('PACKAGE:' + packageName);
  console.log('EMULATOR_SERIAL:' + serial);
  var workflowStarted = startedEmulator;
  var workflowPid = emulatorPid;
  if (
    !workflowStarted &&
    existingSession &&
    existingSession.started === true &&
    existingSession.serial === serial &&
    Number.isSafeInteger(existingSession.pid) &&
    existingSession.pid > 0
  ) {
    workflowStarted = true;
    workflowPid = existingSession.pid;
  }
  console.log('EMULATOR_STARTED:' + (workflowStarted ? 'yes' : 'no'));
  fs.mkdirSync(path.dirname(sessionFile), { recursive: true });
  fs.writeFileSync(
    sessionFile,
    JSON.stringify(
      { serial: serial, started: workflowStarted, pid: workflowPid || undefined },
      null,
      2,
    ) + '\n',
  );
  return 0;
}

module.exports = {
  decodeLocalPropertiesPath: decodeLocalPropertiesPath,
  emulatorAvdName: emulatorAvdName,
  emulatorSerials: emulatorSerials,
  findDebugApk: findDebugApk,
  findSdkTool: findSdkTool,
  listedEmulatorSerials: listedEmulatorSerials,
  ownedRunningSerial: ownedRunningSerial,
  packageFromBadging: packageFromBadging,
  parseArguments: parseArguments,
  preferredEmulatorSerial: preferredEmulatorSerial,
  sdkRoots: sdkRoots,
};

if (require.main === module) {
  main(process.argv.slice(2))
    .then(function (exitCode) {
      process.exitCode = exitCode;
    })
    .catch(function (error) {
      console.log('LAUNCH_STATUS:ERROR');
      console.log(error instanceof Error ? error.message : String(error));
      process.exitCode = 3;
    });
}
